const Login = () => {
  const [formData, setFormData] = useState({ username: '', password: '' });
  const [error, setError] = useState("");
  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://127.0.0.1:8000/api/login/', formData);
      localStorage.setItem('username', res.data.username || formData.username);
      localStorage.setItem('token', res.data.token);
      window.location.href = "/";
    } catch (err) {
      setError("Identifiants incorrects.");
    }
  };
  return (
    <PageLayout title="Connexion">
      <div className="max-w-md mx-auto bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
        {error && <p className="mb-4 text-red-500 text-center font-bold">❌ {error}</p>}
        <form className="space-y-6" onSubmit={handleLogin}>
          <input type="text" placeholder="NOM D'UTILISATEUR" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white font-bold outline-none focus:border-orange-600 transition" onChange={(e) => setFormData({...formData, username: e.target.value})} />
          <input type="password" placeholder="MOT DE PASSE" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white font-bold outline-none focus:border-orange-600 transition" onChange={(e) => setFormData({...formData, password: e.target.value})} />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition">Se Connecter</button>
        </form>
      </div>
    </PageLayout>
  );
};

const Register = () => {
  const [formData, setFormData] = useState({ username: '', email: '', password: '' });
  const [error, setError] = useState("");
  const navigate = useNavigate();
  const handleRegister = async (e) => {
    e.preventDefault();
